mapper.select:
SELECT encode(id, 'hex') AS "deviceId", device_fingerprint AS "deviceFingerprint", current_score AS "currentScore", risk_level AS "riskLevel", first_seen_at AS "firstSeenAt", last_seen_at AS "lastSeenAt", last_login_ip AS "lastLoginIp", linked_user_count AS "linkedUserCount", recent_distinct_ip_count AS "recentDistinctIpCount", recent_ip_switch_count AS "recentIpSwitchCount", last_penalty_reason AS "lastPenaltyReason", last_penalty_score AS "lastPenaltyScore", last_penalty_at AS "lastPenaltyAt" FROM device_risk_profile
AND risk_level = #{riskLevel}
AND current_score >= #{minScore}
AND current_score < #{maxScoreExclusive}
AND (encode(id, 'hex') LIKE #{queryPattern} OR last_login_ip LIKE #{queryPattern})
ORDER BY last_seen_at DESC NULLS LAST, id DESC
ORDER BY current_score ASC, id DESC
